{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_e0031790b5f158d57e244e7f", "claim_ids": ["claim_33e168f2a08797424e05ee98", "claim_e1c3a5a5037b5cb7a1f057db"], "query_ids": ["q_356"], "claims": [{"claim_id": "claim_33e168f2a08797424e05ee98", "quote": "s 9903.82.07, 9903.82.08, 9903.82.10, 9903.82.11, and 9903.82.12 apply only to goods entered before January 1, 2028. From that date, goods currently covered by those headings will fall under 9903.82.05, 9903.82.06, and 9903.82.09 (standard Annex I-B rates).", "url": "https://www.ghy.com/trade-compliance/us-adjusts-section-232-tariffs-on-aluminum-steel-and-copper-full-customs-value-now-applies", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"expiration_date": "January 1, 2028"}}, {"claim_id": "claim_e1c3a5a5037b5cb7a1f057db", "quote": "Headings 9903.82.07, 9903.82.08, 9903.82.10, 9903.82.11, and 9903.82.12 are effective with respect to goods entered for consumption or withdrawn from warehouse for consumption on or after 12:01 a.m. eastern time on April 6, 2026, and before January 1, 2028.", "url": "https://content.govdelivery.com/accounts/USDHSCBP/bulletins/4117593", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"hts_code": "9903.82.07, 9903.82.08, 9903.82.10, 9903.82.11, and 9903.82.12", "effective_date": "April 6, 2026", "expiration_date": "January 1, 2028"}}]}, {"pair_id": "conflict_82a543af7d09345ef2c3171b", "claim_ids": ["claim_650bb58274a32f8294d6a23e", "claim_b76b6de49fa7a55650bc23b7"], "query_ids": ["q_357"], "claims": [{"claim_id": "claim_650bb58274a32f8294d6a23e", "quote": "Section 232 steel tariffs increased from 25% to 50% on June 4, 2025.", "url": "https://gingercontrol.com/blog/how-tariff-stacking-works", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 steel tariffs", "duty_rate": "50%", "effective_date": "June 4, 2025"}}, {"claim_