[{"claim_id": "claim_7eabd75ade67bfb560f39e20", "quote": "Section 232 tariffs on steel and aluminum imports remain at 50%.", "url": "https://www.congress.gov/crs-product/IF10733", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232", "affected_product": "steel and aluminum imports", "duty_rate": "50%"}}, {"claim_id": "claim_8adc495407de3839b4b0f1c1", "quote": "In November 2025, the United States lowered the Section 232 auto tariffs for Korea to 15% (see below).", "url": "https://www.congress.gov/crs-product/IF10733", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "United States", "tariff_program": "Section 232", "duty_rate": "15%", "effective_date": "November 2025"}}]}, {"pair_id": "conflict_100abfceb8bc223594e5f565", "claim_ids": ["claim_3303ee2a79a3fd1dc2e3d095", "claim_67a5aed08108100fa42034ad"], "query_ids": ["q_359"], "claims": [{"claim_id": "claim_3303ee2a79a3fd1dc2e3d095", "quote": "Japan ($69 billion in 2024), which was to face a 25% country-specific tariff.", "url": "https://www.congress.gov/crs-product/IN12608", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%"}}, {"claim_id": "claim_67a5aed08108100fa42034ad", "quote": "In 2025, Trump imposed 25% tariffs on vehicles and auto parts", "url": "https://www.congress.gov/crs-product/IN12608", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariffs", "affected_product": "vehicles and auto parts", "effective_date": "2025"}}]}, {"pair_id": "conflict_421e308adc2968b8160408af", "claim_ids": ["claim_00d4e314940efd08de7c3cf2", "claim_7f86b81edf79f1018a644e9a"], "query_ids": ["q_359"], "claims": [{"claim_id": "claim_00d4e314940efd08de7c3cf2", "quote": "Under the Agreement, the United States will apply a baseline 15 percent tariff on nearly all Japanese imports entering the United States, alongside separate sector-specific treatment for automobiles and automobile parts", "url": "https://www.whitehouse.gov/presidential-actions/2025/09/implementing-the-united-states-japan-agreement", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"duty_rate": "15 percent"}}, {"claim_id": "claim_7f86b81edf79f1018a644e9a", "quote": "the United States imposed a 15% tariff on most imports from Japan, a reduction from the 25% that President Trump initially proposed but an increase from 2024 U.S. tariff rates.", "url": "https://www.congress.gov/crs-product/IN12608", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "15% tariff", "duty_rate": "15%", "announcement_date": "July 2025"}}]}, {"pair_id": "conflict_9f63413e0df0b01b46070931", "claim_ids": ["claim_117a160ac4455f95df00b998", "claim_76f6fc362b5cd8bde5e9bcea"], "query_ids": ["q_36"], "claims": [{"claim_id": "claim_117a160ac4455f95df00b998", "quote": "The Trump administration this past week confirmed plans to lower tariffs on certain products, including vehicles, to 15% from South Korea. A notice about the implementation of the trade deal was posted Wednesday on the Federal Register.", "url": "https://www.cnbc.com/2025/12/03/trump-south-korea-tariffs-vehicles-hyundai-gm.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "lower tariffs on certain products, including vehicles, to 15% from South Korea", "legal_authority": "Federal Register"}}, {"claim_id": "claim_76f6fc362b5cd8bde5e9bcea", "quote": "The South Korean-based automaker is the largest U.S. importer of new vehicles from the country, followed by GM. Both automakers have paid billions of dollars in levies so far this year after President Donald Trump placed 25% tariffs on imported vehicles from South Korea and other countries in the spring.", "url": "https://www.cnbc.com/2025/12/03/trump-south-korea-tariffs-vehicles-hyundai-gm.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariffs on imported vehicles from South Korea", "duty_rate": "25%"}}]}, {"pair_id": "conflict_0e02cf3a7bf0681ab1237aa6", "claim_ids": ["claim_5f8caf338c689621af3cc8f1", "claim_76f6fc362b5cd8bde5e9bcea"], "query_ids": ["q_36"], "claims": [{"claim_id": "claim_5f8caf338c689621af3cc8f1", "quote": "The agreement cuts tariffs on South Korean autos exported to the United States from 25% to 15%, prompting Hyundai and its affiliate Kia Corp to expand domestic production and exports.", "url": "https://www.cbtnews.com/hyundai-to-invest-86-5b-in-south-korea-after-us-tariff-cut", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai", "duty_rate": "15%"}}, {"claim_id": "claim_76f6fc362b5cd8bde5e9bcea", "quote": "The South Korean-based automaker is the largest U.S. importer of new vehicles from the country, followed by GM. Both automakers have paid billions of dollars in levies so far this year after President Donald Trump placed 25% tariffs on imported vehicles from South Korea and other countries in the spring.", "url": "https://www.cnbc.com/2025/12/03/trump-south-korea-tariffs-vehicles-hyundai-gm.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariffs on imported vehicles from South Korea", "duty_rate": "25%"}}]}, {"pair_id": "conflict_e1e2cf283671ed71b60f955b", "claim_ids": ["claim_76f6fc362b5cd8bde5e9bcea", "claim_792cd3fecce66dea42d0f69d"], "query_ids": ["q_36"], "claims": [{"claim_id": "claim_76f6fc362b5cd8bde5e9bcea", "quote": "The South Korean-based automaker is the largest U.S. importer of new vehicles from the country, followed by GM. Both automakers have paid billions of dollars in levies so far this year after President Donald Trump placed 25% tariffs on imported vehicles from South Korea and other countries in the spring.", "url": "https://www.cnbc.com/2025/12/03/trump-south-korea-tariffs-vehicles-hyundai-gm.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariffs on imported vehicles from South Korea", "duty_rate": "25%"}}, {"claim_id": "claim_792cd3fecce66dea42d0f69d", "quote": "U.S.-South Korea trade deal, reducing tariffs to 15% enables Hyundai to diversify exports and support suppliers.", "url": "https://www.cbtnews.com/hyundai-to-invest-86-5b-in-south-korea-after-us-tariff-cut", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai", "tariff_program": "U.S.-South Korea trade deal", "duty_rate": "15%"}}]}, {"pair_id": "conflict_35155aaef9ce5dd2ab157f9f", "claim_ids": ["claim_117a160ac4455f95df00b998", "claim_5f8caf338c689621af3cc8f1"], "query_ids": ["q_36"], "claims": [{"claim_id": "claim_117a160ac4455f95df00b998", "quote": "The Trump administration this past week confirmed plans to lower tariffs on certain products, including vehicles, to 15% from South Korea. A notice about the implementation of the trade deal was posted Wednesday on the Federal Register.", "url": "https://www.cnbc.com/2025/12/03/trump-south-korea-tariffs-vehicles-hyundai-gm.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "lower tariffs on certain products, including vehicles, to 15% from South Korea", "legal_authority": "Federal Register"}}, {"claim_id": "claim_5f8caf338c689621af3cc8f1", "quote": "The agreement cuts tariffs on South Korean autos exported to the United States from 25% to 15%, prompting Hyundai and its affiliate Kia Corp to expand domestic production and exports.", "url": "https://www.cbtnews.com/hyundai-to-invest-86-5b-in-south-korea-after-us-tariff-cut", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Hyundai", "duty_rate": "15%"}}]}]}

